import httpx


def make_proxied_client(proxy_url: str, base_url: str) -> httpx.Client:
    """
    Return an httpx.Client for base_url whose requests (http and https) all go through the HTTP proxy at proxy_url,
    with a 5-second timeout and the header User-Agent: inventory-sync/1.0 on every request.
    """
    proxies = {
        "http://": proxy_url,
        "https://": proxy_url,
    }
    headers = {
        "User-Agent": "inventory-sync/1.0",
    }
    timeout = 5.0
    return httpx.Client(base_url=base_url, proxies=proxies, timeout=timeout, headers=headers)

"""Validate sign-up data with required username and email, optional plan and age."""
from marshmallow import Schema, ValidationError, fields, validates


class SignupSchema(Schema):
    class Meta:
        unknown = "exclude"

    username = fields.String(required=True)
    email = fields.Email(required=True)
    plan = fields.String(missing="free")
    age = fields.Integer(validate=lambda n: 16 <= n <= 120)

    @validates("username")
    def validate_username(self, value):
        if not value.isalnum():
            raise ValidationError("Username must be alphanumeric.")

    @validates("plan")
    def validate_plan(self, value):
        if value not in ("free", "pro", "team"):
            raise ValidationError("Plan must be one of 'free', 'pro', or 'team'.")


def validate_signup(data: dict) -> dict:
    """Validate sign-up data; raise ValueError with .messages on failure."""
    try:
        return SignupSchema().load(data)
    except ValidationError as err:
        exc = ValueError("invalid sign-up data")
        exc.messages = err.messages
        raise exc

